VID.narration = {"look":{"bar":false},"scenes":[{"dur":9.288,"caps":[[0.5,7.47,"Lecture five. Encodings. This is how we write a solution as genes, so that evolution can work on it."]],"warp":[[0,0],[0.5,0.9],[9.288,4]]},{"dur":15.023,"caps":[[0.5,4.99,"A tour visits every city once."],[5.24,13.09,"We write it as genes. Evolution changes the genes."]],"warp":[[0,0],[0.5,0.4],[5.24,4.8],[15.023,10]]},{"dur":14.977,"caps":[[0.5,5.07,"Mutation: pick a gene, give it a random new value."],[5.32,13.01,"Now C is visited twice and D is never visited."]],"warp":[[0,0],[0.5,0.4],[5.32,4],[14.977,11]]},{"dur":15.023,"caps":[[0.5,7.15,"Swap exchanges two genes."],[7.4,14.29,"Nothing is created or lost, so the tour stays valid."]],"warp":[[0,0],[0.5,0.4],[7.4,4],[15.023,9]]},{"dur":16.765,"caps":[[0.5,5.15,"Two parents. Cut both after gene 2."],[5.4,8.61,"Swap the tails to make two children."],[8.86,15.19,"Each child repeats one city and misses another."]],"warp":[[0,0],[0.5,0.4],[5.4,3.5],[8.86,8.4],[16.765,14]]},{"dur":14.884,"caps":[[0.5,4.99,"Repair: find the repeated city and the missing one."],[5.24,10.53,"Put the missing city where the repeat was."],[10.78,13.75,"Both children are valid tours again."]],"warp":[[0,0],[0.5,0.4],[5.24,3.7],[10.78,10.8],[14.884,13]]},{"dur":21.711,"caps":[[0.5,9.31,"Direct: each gene is the slot of one exam."],[9.56,13.33,"Mutation moves just one exam..."],[13.58,20.15,"...but it can create a clash. Fitness must punish it."]],"warp":[[0,0],[0.5,0.4],[9.56,4.5],[13.58,7.2],[21.711,10]]},{"dur":21.618,"caps":[[0.5,8.67,"Indirect: each gene is an instruction for a decoder."],[8.92,14.29,"The decoder never creates a clash."],[14.54,20.87,"One early change moves several exams."]],"warp":[[0,0],[0.5,0.4],[8.92,4],[14.54,7.4],[21.618,11]]},{"dur":26.679,"caps":[[0.5,8.27,"A coordinate is stored as five bits."],[8.52,12.29,"Flip the 1-bit: the value moves 1."],[12.54,16.47,"Flip the 8-bit: it moves 8."],[16.72,22.33,"Flip the sign: + becomes −, a jump of 4."],[22.58,25.23,"Which bit you flip matters."]],"warp":[[0,0],[0.5,0.4],[8.52,2.4],[12.54,5.1],[16.72,8],[22.58,9.5],[26.679,11]]},{"dur":19.993,"caps":[],"warp":[[0,0],[0.5,0.9],[6.84,1.9],[11.82,2.9],[19.993,9]]}]};
